    while (std::regex_search(markdown, match, blockquote_regex)) {
        std::string blockquote_text = match[1].str();
        html << "<blockquote>\n" << blockquote_text << "</blockquote>\n";
        markdown.erase(match.position(), match.length());
    }

    // Convert lists
    std::regex list_regex(R"(^(\*|\-\s).+?$)");

    while (std::regex_search(markdown, match, list_regex)) {
        std::string list_item = match[1].str() + match[0].str().substr(match[1].length());
        html << "<li>" << list_item << "</li>\n";
        markdown.erase(match.position(), match.length());
    }

    // Convert code blocks
    std::regex codeblock_regex(R"(^(\`\`\+?\s*.+?\n.+?\n?\`\`) )");

    while (std::regex_search(markdown, match, codeblock_regex)) {
        std::string language = match[1].str().substr(3, match[1].str().find_first_of(' ') - 3);
        std::string code = match[2].str();
