```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string filename;
    string wordToCount;
    int count = 0;

    // Ask user for input file name and word to count
    cout << "Enter the name of the input file: ";
    getline(cin, filename);
    cout << "Enter the word to count: ";
    getline(cin, wordToCount);

    // Open input file for reading
    ifstream inputFile(filename);
    if (!inputFile) {
        cout << "Error: Could not open file " << filename << endl;
        return 1;
    }

    // Read file line by line and count occurrences of the word
    string line;
    while (getline(inputFile, line)) {
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != string::npos) {
            count++;
            pos += wordToCount.length();
        }
    }

    // Close input file
    inputFile.close();

    // Display the count
    cout << "The word \"" << wordToCount << "\" appears " << count << " times in " << filename << endl;

    return 0;
}
```

